import { alpha, Box, Button, Divider, IconButton, InputBase, Tooltip, Typography } from '@mui/material'
import type { ChangeEvent, KeyboardEvent } from 'react'
import { useCallback, useEffect, useRef, useState, useSyncExternalStore } from 'react'
import Close from 'mdi-material-ui/Close'
import DeleteOutline from 'mdi-material-ui/DeleteOutline'
import FileDocumentOutline from 'mdi-material-ui/FileDocumentOutline'
import FolderSearchOutline from 'mdi-material-ui/FolderSearchOutline'
import type { ProjectCard } from '../../data/data_types'
import { POPOVER_SIDE_MARGIN, POPOVER_TOP_MARGIN, ResizablePopover } from '../resizable_popover'
import { useRunningActionForFile } from '../hooks/use_action_executions'
import { CardBodyEditor } from './card_body_editor'
import { CardDeleteDialog } from './card_delete_dialog'
import { AgentUsageDisplay } from '../agents/agent_usage_display'
import { cardAgentTokenUsage } from '../../services/agents/agent_usage'
import { cardMarkdownDataSource } from '../editor/card_markdown_data_source'
import { MarkdownDocumentHistoryStore } from '../editor/markdown_document_history_store'
import { CardBodySaveStatus } from './card_body_save_status'
import { CardCommitMenu } from './card_commit_menu'
import { CardCommitDiffPanel } from './card_commit_diff_panel'
import { useCardCommits } from '../hooks/use_card_commits'
import type { CardCommit } from '../../services/actions/card_commit_history'
import { openFilesService, type CardOpenDocument } from '../../services/open_files_service'
import { useProjectCard } from './use_project_card'
import { cardBodyPopoverService, subscribeCardBodyPopover } from './card_body_popover_service'

const CARD_BODY_POPOVER_WIDTH = 760
const CARD_BODY_POPOVER_HEIGHT = 620
const CARD_BODY_POPOVER_SIZE_KEY = 'md2.cardBodyPopover.size'

function subscribeOpenDocuments(onStoreChange: () => void) {
    openFilesService.addEventListener('added', onStoreChange)
    openFilesService.addEventListener('removed', onStoreChange)

    return () => {
        openFilesService.removeEventListener('added', onStoreChange)
        openFilesService.removeEventListener('removed', onStoreChange)
    }
}

function useBoardDocument(card: ProjectCard | null, visible: boolean) {
    const getSnapshot = useCallback(() => visible && card
        ? openFilesService.findDocument(card) as CardOpenDocument | null
        : null, [card, visible])

    return useSyncExternalStore(subscribeOpenDocuments, getSnapshot, getSnapshot)
}

interface TitleEdit {
    path: string | null
    title: string
}

interface SelectedCardCommit {
    cardInternalId: string
    commit: CardCommit
}

interface CardBodyPopoverProps {
    isMobile: boolean
    onDeleteCard: (path: string) => Promise<void>
    onOpenAffects: (path: string) => void
    onOpenInFileMode: (path: string) => void
    visible: boolean
}

/** Card details editor anchored to the card that opened it. */
export function CardBodyPopover(props: CardBodyPopoverProps) {
    const {
        isMobile,
        onDeleteCard,
        onOpenAffects,
        onOpenInFileMode,
        visible,
    } = props
    const { anchorElement, cardPath } = useSyncExternalStore(
        subscribeCardBodyPopover,
        () => cardBodyPopoverService.getSnapshot(),
        () => cardBodyPopoverService.getSnapshot(),
    )
    const card = useProjectCard(cardPath)
    const [deleteCardPath, setDeleteCardPath] = useState<string | null>(null)
    const [historyStore] = useState(() => new MarkdownDocumentHistoryStore())
    const cardRef = useRef(card)
    const cardIdentity = card?.header.internalId
    const boardDocument = useBoardDocument(card, visible)
    const [isFullscreen, setIsFullscreen] = useState(false)
    const [popupContentElement, setPopupContentElement] = useState<HTMLDivElement | null>(null)
    const [selectedCardCommit, setSelectedCardCommit] = useState<SelectedCardCommit | null>(null)
    const [titleEdit, setTitleEdit] = useState<TitleEdit>({ path: null, title: '' })
    const titleDraft = titleEdit.path === card?.path ? titleEdit.title : card?.header.title ?? ''
    const cardCommits = useCardCommits(visible ? card?.header.internalId ?? null : null)
    const selectedCommit = visible && selectedCardCommit && selectedCardCommit.cardInternalId === card?.header.internalId
        ? selectedCardCommit.commit
        : null

    useEffect(() => {
        cardRef.current = card
    }, [card])

    useEffect(() => {
        const currentCard = cardRef.current
        if (!visible || !currentCard) {
            cardMarkdownDataSource.setBoardDocument(null)
            historyStore.clear()
            return
        }
        if (!cardIdentity) throw new Error(`Card identity was not added before opening: ${currentCard.path}`)

        const document = openFilesService.openBoardDocument(currentCard)
        cardMarkdownDataSource.setBoardDocument(document)

        return () => {
            cardMarkdownDataSource.setBoardDocument(null)
            historyStore.discardDocument(document)
            openFilesService.closeBoardDocument(document)
        }
    }, [cardIdentity, historyStore, visible])

    useEffect(() => () => {
        cardMarkdownDataSource.setBoardDocument(null)
        historyStore.clear()
    }, [historyStore])

    const closePopover = () => {
        cardMarkdownDataSource.setBoardDocument(null)
        historyStore.clear()
        setIsFullscreen(false)
        setSelectedCardCommit(null)
        setTitleEdit({ path: null, title: '' })
        cardBodyPopoverService.close()
    }

    const handlePopoverClose = (reason?: 'backdropClick' | 'escapeKeyDown') => {
        if (reason === 'escapeKeyDown' && selectedCommit) {
            setSelectedCardCommit(null)
            return
        }
        closePopover()
    }

    const selectCommit = (commit: CardCommit) => {
        if (!card?.header.internalId) throw new Error('Cannot select card commit without an internal ID')
        setSelectedCardCommit({ cardInternalId: card.header.internalId, commit })
    }
    const clearSelectedCommit = () => setSelectedCardCommit(null)

    const openInFileMode = () => {
        if (!card) return
        setIsFullscreen(false)
        onOpenInFileMode(card.path)
    }

    const closeDeleteCardDialog = () => {
        setDeleteCardPath(null)
    }

    const openDeleteCardDialog = () => {
        if (!card) return
        setDeleteCardPath(card.path)
    }

    const openAffects = () => {
        if (card) onOpenAffects(card.path)
    }

    const handleTitleChange = (event: ChangeEvent<HTMLInputElement>) => {
        if (!card) return
        setTitleEdit({ path: card.path, title: event.target.value })
    }

    const commitTitle = () => {
        if (!card) return
        const nextTitle = titleDraft.trim()
        if (nextTitle.length === 0) {
            setTitleEdit({ path: card.path, title: card.header.title })
            return
        }
        if (nextTitle !== card.header.title) cardMarkdownDataSource.updateActiveCardTitle('board-card', nextTitle)
    }

    const handleTitleKeyDown = (event: KeyboardEvent<HTMLInputElement>) => {
        if (event.key === 'Enter') commitTitle()
        if (event.key === 'Escape' && card) setTitleEdit({ path: card.path, title: card.header.title })
    }

    const toggleFullscreen = useCallback(() => {
        setIsFullscreen((current) => !current)
    }, [])

    const deleteCard = async (path: string) => {
        setIsFullscreen(false)
        await onDeleteCard(path)
    }

    const titleId = card ? `card-body-popover-${card.header.internalId}` : 'card-body-popover'
    const runningExecution = useRunningActionForFile(card?.path ?? null)
    const statusLabel = runningExecution ? 'Running' : 'Idle'
    const fullscreenSize = `calc(100vw - ${POPOVER_SIDE_MARGIN * 2}px)`
    const fullscreenHeight = `calc(100vh - ${POPOVER_TOP_MARGIN + POPOVER_SIDE_MARGIN}px)`

    return (
        <>
            <ResizablePopover
                anchorElement={anchorElement}
                initialSize={{ height: CARD_BODY_POPOVER_HEIGHT, width: CARD_BODY_POPOVER_WIDTH }}
                sizeStorageKey={CARD_BODY_POPOVER_SIZE_KEY}
                resizeFromAllSides
                labelId={titleId}
                onClose={handlePopoverClose}
                open={visible && !!card && !!anchorElement}
                paperSx={{
                    backgroundColor: 'background.paper',
                    border: '1px solid',
                    borderColor: 'divider',
                    borderRadius: '14px',
                    boxShadow: '0 24px 60px rgba(16, 24, 40, 0.28)',
                    flexDirection: 'column',
                    height: isFullscreen ? `${fullscreenHeight} !important` : undefined,
                    left: isFullscreen ? `${POPOVER_SIDE_MARGIN}px !important` : undefined,
                    maxHeight: isFullscreen ? 'none' : undefined,
                    maxWidth: isFullscreen ? 'none' : undefined,
                    top: isFullscreen ? `${POPOVER_TOP_MARGIN}px !important` : undefined,
                    transform: isFullscreen ? 'none !important' : undefined,
                    width: isFullscreen ? `${fullscreenSize} !important` : undefined,
                }}
                resizeLabel="Resize card details popup"
            >
                {card ? (
                    <Box
                        ref={setPopupContentElement}
                        sx={{ display: 'flex', flex: 1, flexDirection: 'column', minHeight: 0 }}
                    >
                        <Box
                            sx={{
                                alignItems: 'center',
                                borderBottom: '1px solid',
                                borderColor: 'divider',
                                display: 'flex',
                                flexShrink: 0,
                                gap: '10px',
                                padding: '12px 16px 12px 20px',
                            }}
                        >
                            {/* Visually hidden; provides the dialog's accessible name via aria-labelledby. */}
                            <Typography
                                id={titleId}
                                sx={{
                                    border: 0,
                                    clip: 'rect(0 0 0 0)',
                                    height: '1px',
                                    margin: '-1px',
                                    overflow: 'hidden',
                                    padding: 0,
                                    position: 'absolute',
                                    whiteSpace: 'nowrap',
                                    width: '1px',
                                }}
                            >
                                {card.header.id} card details
                            </Typography>
                            <Box
                                component="span"
                                sx={(theme) => ({
                                    backgroundColor: alpha(theme.palette.primary.main, theme.palette.mode === 'dark' ? 0.16 : 0.1),
                                    borderRadius: '5px',
                                    color: 'primary.main',
                                    flexShrink: 0,
                                    fontFamily: '"Roboto Mono", ui-monospace, monospace',
                                    fontSize: 12,
                                    fontWeight: 600,
                                    padding: '3px 8px',
                                })}
                            >
                                {card.header.id}
                            </Box>
                            <InputBase
                                aria-label="Card title"
                                onBlur={commitTitle}
                                onChange={handleTitleChange}
                                onKeyDown={handleTitleKeyDown}
                                placeholder="Card title"
                                sx={(theme) => ({
                                    '&:focus-within': {
                                        backgroundColor: 'background.paper',
                                        borderColor: 'primary.main',
                                        boxShadow: `0 0 0 3px ${alpha(theme.palette.primary.main, 0.12)}`,
                                    },
                                    '&:hover:not(:focus-within)': { backgroundColor: 'action.hover' },
                                    '& input': { height: '34px', padding: '0 10px' },
                                    backgroundColor: 'transparent',
                                    border: '1px solid transparent',
                                    borderRadius: '8px',
                                    color: 'text.primary',
                                    flex: 1,
                                    fontSize: 16,
                                    fontWeight: 700,
                                    minWidth: 0,
                                })}
                                value={titleDraft}
                            />
                            <CardCommitMenu commits={cardCommits.commits} error={cardCommits.error} onSelect={selectCommit} />
                            <Box sx={{
                                alignItems: 'center',
                                color: 'text.disabled',
                                display: 'flex',
                                flexShrink: 0,
                                fontSize: 11.5,
                                gap: '5px',
                            }}>
                                <Box sx={{ backgroundColor: runningExecution ? 'success.main' : 'text.disabled', borderRadius: '50%', height: 7, width: 7 }} />
                                {statusLabel}
                            </Box>
                            <Divider orientation="vertical" sx={{ borderColor: 'divider', height: 20 }} />
                            {boardDocument ? <CardBodySaveStatus document={boardDocument} /> : null}

                            <Tooltip title="Close">
                                <IconButton aria-label="Close card details" onClick={closePopover} size="small" sx={{ height: 30, ml: '4px', width: 30 }}>
                                    <Close sx={{ fontSize: 17 }} />
                                </IconButton>
                            </Tooltip>
                        </Box>

                        {selectedCommit ? (
                            <CardCommitDiffPanel
                                binding="board-card"
                                commit={selectedCommit}
                                key={selectedCommit.commit}
                                onExit={clearSelectedCommit}
                            />
                        ) : null}
                        <Box
                            hidden={!!selectedCommit}
                            sx={{ display: selectedCommit ? 'none' : 'flex', flex: 1, flexDirection: 'column', minHeight: 0 }}
                        >
                            <CardBodyEditor
                                historyStore={historyStore}
                                isFullscreen={isFullscreen}
                                isMobile={isMobile}
                                onToggleFullscreen={toggleFullscreen}
                                overlayContainer={popupContentElement}
                            />
                        </Box>

                        <Box
                            sx={{
                                alignItems: 'center',
                                backgroundColor: 'background.default',
                                borderTop: '1px solid',
                                borderColor: 'divider',
                                display: 'flex',
                                flexShrink: 0,
                                gap: '8px',
                                padding: '12px 16px',
                            }}
                        >
                            <Button color="error" onClick={openDeleteCardDialog} startIcon={<DeleteOutline />} variant="outlined">Delete</Button>
                            <Button onClick={openAffects} startIcon={<FolderSearchOutline />} variant="outlined">Affects</Button>
                            <Button onClick={openInFileMode} startIcon={<FileDocumentOutline />} variant="outlined">Open in file mode</Button>
                            <AgentUsageDisplay usage={cardAgentTokenUsage(card)} />
                            <Box sx={{ flex: 1 }} />
                            <Button onClick={closePopover} variant="contained">Close</Button>
                        </Box>
                    </Box>
                ) : null}
            </ResizablePopover>
            <CardDeleteDialog cardPath={visible ? deleteCardPath : null} onClose={closeDeleteCardDialog} onDeleteCard={deleteCard} />
        </>
    )
}

import { Box } from '@mui/material'
import { memo, useCallback } from 'react'
import { MarkdownEditor } from '../editor/markdown_editor'
import { cardMarkdownDataSource } from '../editor/card_markdown_data_source'
import type { MarkdownDocumentHistoryStore } from '../editor/markdown_document_history_store'
import { CardPopupToolbarControls } from './card_popup_toolbar_controls'

interface CardBodyEditorProps {
    historyStore: MarkdownDocumentHistoryStore
    isMobile?: boolean
    isFullscreen: boolean
    onToggleFullscreen: () => void
    overlayContainer?: HTMLElement | null
}

/**
 * Body editing surface for a card, bound directly to the card Markdown data source.
 */
export const CardBodyEditor = memo(function CardBodyEditor(props: CardBodyEditorProps) {
    const { historyStore, isFullscreen, isMobile = false, onToggleFullscreen, overlayContainer } = props
    const ToolbarContents = useCallback(
        () => <CardPopupToolbarControls isFullscreen={isFullscreen} onToggleFullscreen={onToggleFullscreen} />,
        [isFullscreen, onToggleFullscreen],
    )
    return (
        <Box
            sx={{
                '& .mdxeditor-content': {
                    boxSizing: 'border-box',
                    minHeight: 220,
                    padding: '26px 28px 32px',
                },
                '& [class*="_toolbarButton_"], & [class*="_toolbarToggleItem_"]': {
                    alignItems: 'center',
                    borderRadius: '6px',
                    cursor: 'pointer',
                    display: 'flex',
                    height: 30,
                    justifyContent: 'center',
                    width: 30,
                },
                '& [class*="_toolbarButton_"]:hover, & [class*="_toolbarToggleItem_"]:hover': {
                    backgroundColor: 'background.paper',
                    color: 'text.primary',
                },
                '& [class*="_toolbarRoot_"]': {
                    backgroundColor: 'action.selected',
                    borderRadius: '9px',
                    boxSizing: 'border-box',
                    color: 'text.secondary',
                    flexShrink: 0,
                    height: 40,
                    margin: '14px 20px 0',
                    padding: '0 6px',
                    top: isMobile ? 0 : 'auto',
                    width: 'auto',
                },
                '& [class*="_toolbarRoot_"] div[role="separator"]': {
                    borderColor: 'divider',
                    height: 20,
                    margin: '0 4px',
                },
                flex: 1,
                minHeight: 0,
                overflow: 'auto',
            }}
        >
            <MarkdownEditor
                binding="board-card"
                dataSource={cardMarkdownDataSource}
                historyStore={historyStore}
                overlayContainer={overlayContainer}
                stickyToolbar={isMobile}
                toolbarContents={ToolbarContents}
            />
        </Box>
    )
})

import { Box, IconButton, Tooltip } from '@mui/material'
import Fullscreen from 'mdi-material-ui/Fullscreen'
import FullscreenExit from 'mdi-material-ui/FullscreenExit'
import { MarkdownFormatToolbarControls } from '../editor/markdown_format_toolbar_controls'

interface CardPopupToolbarControlsProps {
    isFullscreen: boolean
    onToggleFullscreen: () => void
}

/** Formatting controls arranged for the card details popup. */
export function CardPopupToolbarControls(props: CardPopupToolbarControlsProps) {
    const { isFullscreen, onToggleFullscreen } = props
    const label = isFullscreen ? 'Exit fullscreen' : 'Fullscreen'

    return (
        <MarkdownFormatToolbarControls endControls={(
            <>
                <Box sx={{ flex: 1 }} />
                <Tooltip title={label}>
                    <IconButton aria-label={label} onClick={onToggleFullscreen} size="small" sx={{ height: 30, width: 30 }}>
                        {isFullscreen ? <FullscreenExit sx={{ fontSize: 17 }} /> : <Fullscreen sx={{ fontSize: 17 }} />}
                    </IconButton>
                </Tooltip>
            </>
        )} />
    )
}

import { Box, Popover } from '@mui/material'
import type { PopoverOrigin, SxProps, Theme } from '@mui/material'
import { useEffect, useRef, useState } from 'react'
import type { PointerEvent as ReactPointerEvent, ReactNode } from 'react'

export type ResizeCorner = 'lower-left' | 'lower-right'

interface PopoverSize {
    height?: number
    width?: number
}

interface ResizablePopoverProps {
    anchorElement: HTMLElement | null
    anchorOrigin?: PopoverOrigin
    children: ReactNode
    initialSize: PopoverSize
    labelId: string
    onClose: (reason?: 'backdropClick' | 'escapeKeyDown') => void
    open: boolean
    paperSx?: SxProps<Theme>
    resizeCorner?: ResizeCorner
    resizeFromAllSides?: boolean
    resizeLabel: string
    /** When set, the last dragged size is remembered in localStorage under this key. */
    sizeStorageKey?: string
    transformOrigin?: PopoverOrigin
}

const MIN_WIDTH = 280
const MIN_HEIGHT = 200
/** Keeps the popover below the window's toolbar drag region so it stays grabbable and closable. */
export const POPOVER_TOP_MARGIN = 60
export const POPOVER_SIDE_MARGIN = 16
const HANDLE_SIZE = 16
const EDGE_HANDLE_SIZE = 6
const ALL_RESIZE_DIRECTIONS = ['top', 'right', 'bottom', 'left', 'top-right', 'bottom-right', 'bottom-left', 'top-left'] as const
type ResizeDirection = typeof ALL_RESIZE_DIRECTIONS[number]

function readStoredSize(storageKey: string | undefined): PopoverSize | null {
    if (!storageKey) return null

    const stored = window.localStorage.getItem(storageKey)
    if (!stored) return null

    const parsed = JSON.parse(stored) as PopoverSize
    const height = typeof parsed.height === 'number' ? Math.max(MIN_HEIGHT, parsed.height) : undefined
    const width = typeof parsed.width === 'number' ? Math.max(MIN_WIDTH, parsed.width) : undefined
    if (height === undefined && width === undefined) return null

    return { height, width }
}

function maxPopoverHeight() {
    return Math.max(MIN_HEIGHT, window.innerHeight - POPOVER_TOP_MARGIN - POPOVER_SIDE_MARGIN)
}

function maxPopoverWidth() {
    return Math.max(MIN_WIDTH, window.innerWidth - POPOVER_SIDE_MARGIN * 2)
}

function directionCursor(direction: ResizeDirection) {
    if (direction === 'top' || direction === 'bottom') return 'ns-resize'
    if (direction === 'left' || direction === 'right') return 'ew-resize'
    if (direction === 'top-right' || direction === 'bottom-left') return 'nesw-resize'
    return 'nwse-resize'
}

function directionPosition(direction: ResizeDirection) {
    const isCorner = direction.includes('-')
    const touchesTop = direction.startsWith('top')
    const touchesBottom = direction.startsWith('bottom')
    const touchesLeft = direction.endsWith('left') || direction === 'left'
    const touchesRight = direction.endsWith('right') || direction === 'right'

    return {
        bottom: touchesBottom ? 0 : undefined,
        cursor: directionCursor(direction),
        height: isCorner ? HANDLE_SIZE : touchesTop || touchesBottom ? EDGE_HANDLE_SIZE : `calc(100% - ${HANDLE_SIZE * 2}px)`,
        left: touchesLeft ? 0 : direction === 'top' || direction === 'bottom' ? HANDLE_SIZE : undefined,
        right: touchesRight ? 0 : undefined,
        top: touchesTop ? 0 : direction === 'left' || direction === 'right' ? HANDLE_SIZE : undefined,
        width: isCorner ? HANDLE_SIZE : touchesLeft || touchesRight ? EDGE_HANDLE_SIZE : `calc(100% - ${HANDLE_SIZE * 2}px)`,
    }
}

/** An anchored popover with configurable drag handles for resizing its content. */
export function ResizablePopover(props: ResizablePopoverProps) {
    const {
        anchorElement,
        anchorOrigin = { horizontal: 'left', vertical: 'bottom' },
        children,
        initialSize,
        labelId,
        onClose,
        open,
        paperSx,
        resizeCorner = 'lower-right',
        resizeFromAllSides = false,
        resizeLabel,
        sizeStorageKey,
        transformOrigin = { horizontal: 'left', vertical: 'top' },
    } = props
    const [size, setSize] = useState<PopoverSize>(() => readStoredSize(sizeStorageKey) ?? initialSize)
    const paperRef = useRef<HTMLDivElement | null>(null)
    const resizeRef = useRef<AbortController | null>(null)

    useEffect(() => () => resizeRef.current?.abort(), [])

    const handleClose = (_event: unknown, reason: 'backdropClick' | 'escapeKeyDown') => {
        resizeRef.current?.abort()
        onClose(reason)
    }

    const startResize = (event: ReactPointerEvent) => {
        event.preventDefault()
        resizeRef.current?.abort()

        if (!paperRef.current) throw new Error('Missing resizable popover paper element')

        const direction = event.currentTarget.getAttribute('data-direction') as ResizeDirection | null
        const controller = new AbortController()
        const bounds = paperRef.current.getBoundingClientRect()
        const start = {
            height: size.height ?? bounds.height,
            width: size.width ?? bounds.width,
            x: event.clientX,
            y: event.clientY,
        }
        resizeRef.current = controller

        window.addEventListener('pointermove', (move: PointerEvent) => {
            const activeDirection = direction ?? (resizeCorner === 'lower-left' ? 'bottom-left' : 'bottom-right')
            const horizontalDelta = move.clientX - start.x
            const verticalDelta = move.clientY - start.y
            const resizesLeft = activeDirection.includes('left')
            const resizesRight = activeDirection.includes('right')
            const resizesTop = activeDirection.includes('top')
            const resizesBottom = activeDirection.includes('bottom')
            const width = Math.max(MIN_WIDTH, start.width + (resizesLeft ? -horizontalDelta : resizesRight ? horizontalDelta : 0))
            const height = Math.max(MIN_HEIGHT, start.height + (resizesTop ? -verticalDelta : resizesBottom ? verticalDelta : 0))

            setSize({ height: Math.min(height, maxPopoverHeight()), width: Math.min(width, maxPopoverWidth()) })
        }, { signal: controller.signal })
        window.addEventListener('pointerup', () => {
            controller.abort()
            if (sizeStorageKey && paperRef.current) {
                const paperBounds = paperRef.current.getBoundingClientRect()
                window.localStorage.setItem(sizeStorageKey, JSON.stringify({ height: paperBounds.height, width: paperBounds.width }))
            }
        }, { signal: controller.signal })
    }

    return (
        <Popover
            anchorEl={anchorElement}
            anchorOrigin={anchorOrigin}
            marginThreshold={POPOVER_TOP_MARGIN}
            onClose={handleClose}
            open={open}
            slotProps={{
                paper: {
                    'aria-labelledby': labelId,
                    ref: paperRef,
                    role: 'dialog',
                    style: size,
                    sx: [{
                        display: 'flex',
                        maxHeight: `calc(100vh - ${POPOVER_TOP_MARGIN + POPOVER_SIDE_MARGIN}px)`,
                        maxWidth: `calc(100vw - ${POPOVER_SIDE_MARGIN * 2}px)`,
                        overflow: 'hidden',
                        position: 'relative',
                    }, paperSx] as SxProps<Theme>,
                },
            }}
            transformOrigin={transformOrigin}
        >
            {children}
            {resizeFromAllSides ? ALL_RESIZE_DIRECTIONS.map((direction) => (
                <Box
                    aria-label={`${resizeLabel} from ${direction}`}
                    data-direction={direction}
                    key={direction}
                    onPointerDown={startResize}
                    role="separator"
                    sx={{ ...directionPosition(direction), position: 'absolute', touchAction: 'none' }}
                />
            )) : (
                <Box
                    aria-label={resizeLabel}
                    data-corner={resizeCorner}
                    onPointerDown={startResize}
                    role="separator"
                    sx={{
                        bottom: 0,
                        cursor: resizeCorner === 'lower-left' ? 'nesw-resize' : 'nwse-resize',
                        height: HANDLE_SIZE,
                        left: resizeCorner === 'lower-left' ? 0 : undefined,
                        position: 'absolute',
                        right: resizeCorner === 'lower-right' ? 0 : undefined,
                        touchAction: 'none',
                        width: HANDLE_SIZE,
                    }}
                />
            )}
        </Popover>
    )
}

import { Box } from '@mui/material'
import { DndContext, DragOverlay, PointerSensor, closestCorners, useSensor, useSensors } from '@dnd-kit/core'
import type { DragEndEvent, DragMoveEvent, DragStartEvent } from '@dnd-kit/core'
import { useCallback, useEffect, useRef, useState } from 'react'
import { buildCardColumns } from '../../data/card_ordering'
import type { CardTypeConfig, StateConfig } from '../../data/data_types'
import { useAgentAcknowledgements } from '../hooks/use_agent_acknowledgements'
import { dataService } from '../../services/data/data_service'
import { dialogService } from '../../services/dialog_service'
