        try {
            await dataService.cards.createMarkdownFile(parentDirectory, name)
        } catch (error) {
            dialogService.error(error, { fallbackMessage: `Markdown file creation failed: ${name}` })
            throw error
        }
    }, [])

    const handleDeleteFile = useCallback(async (path: string) => {
        try {
